code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Solid non-background rows and columns are panel dividers.
    hcuts = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    vcuts = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    def ranges(n, cuts):
        result, start = [], 0
        for p in cuts + [n]:
            if start < p:
                result.append((start, p))
            start = p + 1
        return result
    row_ranges, col_ranges = ranges(h, hcuts), ranges(w, vcuts)
    panels = []
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges:
            if any(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)):
                panels.append((r0, r1, c0, c1))
    out = [row[:] for row in grid]
    if not panels:
        return out
    r0, r1, c0, c1 = panels[0]
    pattern = [row[c0:c1] for row in grid[r0:r1]]
    for a, b in row_ranges:
        for x, y in col_ranges:
            if (a, b, x, y) in panels:
                continue
            if (b - a, y - x) != (len(pattern), len(pattern[0])):
                continue
            for i in range(b - a):
                out[a + i][x:y] = pattern[i][:]
    return out
'''
